    public companion object {
        /**
         * Subscribes to every stream, in Generator's numbering, and builds the model from what they replay. Each message
         * is decoded whole, then applied (the connection checks every byte was read in between).
         *
         * @throws OahuContractException when a state stream replays nothing; the connection is closed first, so the
         *   provider refuses the screen with nothing left subscribed.
         */
        public fun connect(port: Port): GeneratorModel {
            val connection = OahuConnection(port)
            try {
                val copy = connection.subscribeState(
                    GeneratorContract.STREAM_COPY,
                    GeneratorCopyOahuCodec::readGeneratorCopy,
                )
                val palette = connection.subscribeState(
                    GeneratorContract.STREAM_PALETTE,
                    AppPaletteOahuCodec::readAppPalette,
                )
                val layout = connection.subscribeState(
                    GeneratorContract.STREAM_LAYOUT,
                    GeneratorLayoutOahuCodec::readGeneratorLayout,
                )
                val locks = connection.subscribeState(
                    GeneratorContract.STREAM_LOCKS,
                    GeneratorPolicyLocksOahuCodec::readGeneratorPolicyLocks,
                )
                val generated = connection.subscribeState(
                    GeneratorContract.STREAM_GENERATED,
                    { r1 -> r1.readList(TextRunOahuCodec::readTextRun) },
                )
                val kind = connection.subscribeEditable(
                    GeneratorContract.STREAM_KIND,
                    GeneratorContract.MEMBER_EDIT_KIND,
                    GeneratorKindOahuCodec::readGeneratorKind,
                    GeneratorKindOahuCodec::writeGeneratorKind,
                )
                val passwordType = connection.subscribeEditable(
                    GeneratorContract.STREAM_PASSWORD_TYPE,
                    GeneratorContract.MEMBER_EDIT_PASSWORD_TYPE,
                    PasswordKindOahuCodec::readPasswordKind,
                    PasswordKindOahuCodec::writePasswordKind,
                )
                val length = connection.subscribeEditable(
                    GeneratorContract.STREAM_LENGTH,
                    GeneratorContract.MEMBER_EDIT_LENGTH,
                    OahuReader::readInt,
                    OahuWriter::writeInt,
                )
                val uppercase = connection.subscribeEditable(
                    GeneratorContract.STREAM_UPPERCASE,
                    GeneratorContract.MEMBER_EDIT_UPPERCASE,
                    OahuReader::readBool,
                    OahuWriter::writeBool,
                )
                val lowercase = connection.subscribeEditable(
                    GeneratorContract.STREAM_LOWERCASE,
                    GeneratorContract.MEMBER_EDIT_LOWERCASE,
                    OahuReader::readBool,
                    OahuWriter::writeBool,
                )
                val numbers = connection.subscribeEditable(
                    GeneratorContract.STREAM_NUMBERS,
                    GeneratorContract.MEMBER_EDIT_NUMBERS,
                    OahuReader::readBool,
                    OahuWriter::writeBool,
                )
                val special = connection.subscribeEditable(
                    GeneratorContract.STREAM_SPECIAL,
                    GeneratorContract.MEMBER_EDIT_SPECIAL,
                    OahuReader::readBool,
                    OahuWriter::writeBool,
                )
                val minNumbers = connection.subscribeEditable(
                    GeneratorContract.STREAM_MIN_NUMBERS,
                    GeneratorContract.MEMBER_EDIT_MIN_NUMBERS,
                    OahuReader::readInt,
                    OahuWriter::writeInt,
                )
                val minSpecial = connection.subscribeEditable(
                    GeneratorContract.STREAM_MIN_SPECIAL,
                    GeneratorContract.MEMBER_EDIT_MIN_SPECIAL,
                    OahuReader::readInt,
                    OahuWriter::writeInt,
                )
                val avoidAmbiguous = connection.subscribeEditable(
                    GeneratorContract.STREAM_AVOID_AMBIGUOUS,
                    GeneratorContract.MEMBER_EDIT_AVOID_AMBIGUOUS,
                    OahuReader::readBool,
                    OahuWriter::writeBool,
                )
                val numberOfWords = connection.subscribeEditable(
                    GeneratorContract.STREAM_NUMBER_OF_WORDS,
                    GeneratorContract.MEMBER_EDIT_NUMBER_OF_WORDS,
                    OahuReader::readInt,
                    OahuWriter::writeInt,
                )
                val wordSeparator = connection.subscribeEditable(
                    GeneratorContract.STREAM_WORD_SEPARATOR,
                    GeneratorContract.MEMBER_EDIT_WORD_SEPARATOR,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val capitalize = connection.subscribeEditable(
                    GeneratorContract.STREAM_CAPITALIZE,
                    GeneratorContract.MEMBER_EDIT_CAPITALIZE,
                    OahuReader::readBool,
                    OahuWriter::writeBool,
                )
                val includeNumber = connection.subscribeEditable(
                    GeneratorContract.STREAM_INCLUDE_NUMBER,
                    GeneratorContract.MEMBER_EDIT_INCLUDE_NUMBER,
                    OahuReader::readBool,
                    OahuWriter::writeBool,
                )
                val usernameType = connection.subscribeEditable(
                    GeneratorContract.STREAM_USERNAME_TYPE,
                    GeneratorContract.MEMBER_EDIT_USERNAME_TYPE,
                    UsernameKindOahuCodec::readUsernameKind,
                    UsernameKindOahuCodec::writeUsernameKind,
                )
                val plusAddressedEmail = connection.subscribeEditable(
                    GeneratorContract.STREAM_PLUS_ADDRESSED_EMAIL,
                    GeneratorContract.MEMBER_EDIT_PLUS_ADDRESSED_EMAIL,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val plusAddressedEmailType = connection.subscribeEditable(
                    GeneratorContract.STREAM_PLUS_ADDRESSED_EMAIL_TYPE,
                    GeneratorContract.MEMBER_EDIT_PLUS_ADDRESSED_EMAIL_TYPE,
                    EmailKindOahuCodec::readEmailKind,
                    EmailKindOahuCodec::writeEmailKind,
                )
                val catchAllDomain = connection.subscribeEditable(
                    GeneratorContract.STREAM_CATCH_ALL_DOMAIN,
                    GeneratorContract.MEMBER_EDIT_CATCH_ALL_DOMAIN,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val catchAllEmailType = connection.subscribeEditable(
                    GeneratorContract.STREAM_CATCH_ALL_EMAIL_TYPE,
                    GeneratorContract.MEMBER_EDIT_CATCH_ALL_EMAIL_TYPE,
                    EmailKindOahuCodec::readEmailKind,
                    EmailKindOahuCodec::writeEmailKind,
                )
                val service = connection.subscribeEditable(
                    GeneratorContract.STREAM_SERVICE,
                    GeneratorContract.MEMBER_EDIT_SERVICE,
                    ForwardedServiceOahuCodec::readForwardedService,
                    ForwardedServiceOahuCodec::writeForwardedService,
                )
                val apiSecret = connection.subscribeEditable(
                    GeneratorContract.STREAM_API_SECRET,
                    GeneratorContract.MEMBER_EDIT_API_SECRET,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val addyIoDomain = connection.subscribeEditable(
                    GeneratorContract.STREAM_ADDY_IO_DOMAIN,
                    GeneratorContract.MEMBER_EDIT_ADDY_IO_DOMAIN,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val forwardEmailDomain = connection.subscribeEditable(
                    GeneratorContract.STREAM_FORWARD_EMAIL_DOMAIN,
                    GeneratorContract.MEMBER_EDIT_FORWARD_EMAIL_DOMAIN,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val capitalizeRandomWord = connection.subscribeEditable(
                    GeneratorContract.STREAM_CAPITALIZE_RANDOM_WORD,
                    GeneratorContract.MEMBER_EDIT_CAPITALIZE_RANDOM_WORD,
                    OahuReader::readBool,
                    OahuWriter::writeBool,
                )
                val includeNumberRandomWord = connection.subscribeEditable(
                    GeneratorContract.STREAM_INCLUDE_NUMBER_RANDOM_WORD,
                    GeneratorContract.MEMBER_EDIT_INCLUDE_NUMBER_RANDOM_WORD,
                    OahuReader::readBool,
                    OahuWriter::writeBool,
                )
                val copied = OahuEvents<Unit>()
                connection.subscribe(GeneratorContract.STREAM_COPIED, { _ -> }, copied::emit)
                return GeneratorModel(
                    connection,
                    copy,
                    palette,
                    layout,
                    locks,
                    generated,
                    kind,
                    passwordType,
                    length,
                    uppercase,
                    lowercase,
                    numbers,
                    special,
                    minNumbers,
                    minSpecial,
                    avoidAmbiguous,
                    numberOfWords,
                    wordSeparator,
                    capitalize,
                    includeNumber,
                    usernameType,
                    plusAddressedEmail,
                    plusAddressedEmailType,
                    catchAllDomain,
                    catchAllEmailType,
                    service,
                    apiSecret,
                    addyIoDomain,
                    forwardEmailDomain,
                    capitalizeRandomWord,
                    includeNumberRandomWord,
                    copied,
                )
            } catch (failure: Throwable) {
                connection.close()
                throw failure
            }
        }

        /**
         * The real model over an [OahuPreviewPort] that replays these values. Methods without handlers
         * have no effect. [configure] runs on a [Preview] before the model connects.
         */
        public fun preview(
            copy: GeneratorCopy,
            palette: AppPalette,
            layout: GeneratorLayout,
            locks: GeneratorPolicyLocks,
            generated: List<TextRun>,
            kind: GeneratorKind,
            passwordType: PasswordKind,
            length: Int,
            uppercase: Boolean,
            lowercase: Boolean,
            numbers: Boolean,
            special: Boolean,
            minNumbers: Int,
            minSpecial: Int,
            avoidAmbiguous: Boolean,
            numberOfWords: Int,
            wordSeparator: String,
            capitalize: Boolean,
            includeNumber: Boolean,
            usernameType: UsernameKind,
            plusAddressedEmail: String,
            plusAddressedEmailType: EmailKind,
            catchAllDomain: String,
            catchAllEmailType: EmailKind,
            service: ForwardedService,
            apiSecret: String,
            addyIoDomain: String,
            forwardEmailDomain: String,
            capitalizeRandomWord: Boolean,
            includeNumberRandomWord: Boolean,
            configure: Preview.() -> Unit = {},
        ): GeneratorModel {
            val port = OahuPreviewPort(GeneratorContract.NAME, GeneratorContract.HASH)
            port.setState(GeneratorContract.STREAM_COPY) { GeneratorCopyOahuCodec.writeGeneratorCopy(it, copy) }
            port.setState(GeneratorContract.STREAM_PALETTE) { AppPaletteOahuCodec.writeAppPalette(it, palette) }
            port.setState(GeneratorContract.STREAM_LAYOUT) { GeneratorLayoutOahuCodec.writeGeneratorLayout(it, layout) }
            port.setState(GeneratorContract.STREAM_LOCKS) { GeneratorPolicyLocksOahuCodec.writeGeneratorPolicyLocks(it, locks) }
            port.setState(GeneratorContract.STREAM_GENERATED) { it.writeList(generated, TextRunOahuCodec::writeTextRun) }
            port.setState(GeneratorContract.STREAM_KIND) { GeneratorKindOahuCodec.writeGeneratorKind(it, kind) }
            port.setState(GeneratorContract.STREAM_PASSWORD_TYPE) { PasswordKindOahuCodec.writePasswordKind(it, passwordType) }
            port.setState(GeneratorContract.STREAM_LENGTH) { it.writeInt(length) }
            port.setState(GeneratorContract.STREAM_UPPERCASE) { it.writeBool(uppercase) }
            port.setState(GeneratorContract.STREAM_LOWERCASE) { it.writeBool(lowercase) }
            port.setState(GeneratorContract.STREAM_NUMBERS) { it.writeBool(numbers) }
            port.setState(GeneratorContract.STREAM_SPECIAL) { it.writeBool(special) }
            port.setState(GeneratorContract.STREAM_MIN_NUMBERS) { it.writeInt(minNumbers) }
            port.setState(GeneratorContract.STREAM_MIN_SPECIAL) { it.writeInt(minSpecial) }
            port.setState(GeneratorContract.STREAM_AVOID_AMBIGUOUS) { it.writeBool(avoidAmbiguous) }
            port.setState(GeneratorContract.STREAM_NUMBER_OF_WORDS) { it.writeInt(numberOfWords) }
            port.setState(GeneratorContract.STREAM_WORD_SEPARATOR) { it.writeString(wordSeparator) }
            port.setState(GeneratorContract.STREAM_CAPITALIZE) { it.writeBool(capitalize) }
            port.setState(GeneratorContract.STREAM_INCLUDE_NUMBER) { it.writeBool(includeNumber) }
